"""Random small-case fuzz: engine output vs independent brute-force optimum."""
import json
import random
import subprocess
import sys

sys.path.insert(0, '/workspace/tmp/tests')
sys.path.insert(0, '/workspace')
import brutelib
from audit import audit

U = 1 << 128

def rand_key(rng, kind):
    if kind == 0:
        return rng.randrange(U)
    if kind == 1:
        return rng.choice([0, 1, 2, U - 1, U - 2, (1 << 64), (1 << 127)])
    return rng.randrange(1 << 16)

def fmt_addr(a):
    h = format(a, '032x')
    return ':'.join(h[i:i+4] for i in range(0, 32, 4))

def fmt_prefix(r):
    s, ln = r
    h = format(s, '032x')
    return ':'.join(h[i:i+4] for i in range(0, 32, 4)) + '/' + str(ln)

def gen_case(rng, max_routes=5, max_ver=4, max_bursts=4):
    nv = rng.randint(1, max_ver)
    def rand_route():
        length = rng.choice([0, 1, 32, 64, 96, 127, 128, rng.randint(0, 128)])
        size = 1 << (128 - length)
        start = (rand_key(rng, rng.randint(0, 2)) // size) * size
        return (start, length)
    initial = []
    routes = {}
    for _ in range(rng.randint(0, max_routes)):
        r = rand_route()
        hop = rng.choice([0, 1, 2, 7, 2147483647, rng.randint(0, 10)])
        initial.append((r, hop))
        routes[r] = hop
    history = [dict(routes)]
    transactions = []
    for _ in range(nv - 1):
        txrow = []
        for _ in range(rng.randint(0, 3)):
            if rng.random() < 0.6:
                r = rand_route()
                hop = rng.randint(0, 5)
                txrow.append(('set', r, hop))
                routes[r] = hop
            else:
                r = rand_route()
                txrow.append(('erase', r, None))
                routes.pop(r, None)
        transactions.append(txrow)
        history.append(dict(routes))
    pool = [0, 1, U - 1, rand_key(rng, 0)]
    for r in list(routes) + [rr for (rr, _) in initial]:
        pool.append(r[0])
        pool.append(r[0] + (1 << (128 - r[1])) - 1 if r[1] > 0 else U - 1)
        pool.append(min(U - 1, r[0] + (1 << max(0, 127 - r[1]))))
    pool = [min(x, U - 1) for x in pool]
    bursts = []
    for _ in range(rng.randint(0, max_bursts)):
        v = rng.randrange(nv)
        rep = rng.choice([1, 2, 5, 1000000, rng.randint(1, 50)])
        addrs = [rng.choice(pool) for _ in range(rng.randint(0, 5))]
        bursts.append((v, rep, addrs))
    cache_pages = rng.randint(0, 3)
    hit = rng.randint(1, 16)
    miss = rng.randint(hit, 32)
    dec = [rng.randint(0, 16) for _ in range(3)]
    return {
        'history': history, 'transactions': transactions, 'bursts': bursts,
        'cache_pages': cache_pages, 'costs': (hit, miss, dec),
    }, initial

def build_request(rng, ncases=1, R_cap=5):
    cases, raw_cases = [], []
    for _ in range(ncases * 6):
        if len(cases) >= ncases:
            break
        case, initial = gen_case(rng)
        ok, total = True, 0
        for h in case['history']:
            runs = brutelib.compile_runs(h)
            if len(runs) > R_cap:
                ok = False
            total += len(runs)
        if not ok or total > 14:
            continue
        raw = {
            'initial': [[fmt_prefix(r), hop] for (r, hop) in initial],
            'transactions': [[(['set', fmt_prefix(op[1]), op[2]] if op[0] == 'set'
                               else ['erase', fmt_prefix(op[1])]) for op in tx]
                             for tx in case['transactions']],
            'bursts': [{'version': v, 'repeat': rep,
                        'addresses': [fmt_addr(a) for a in addrs]}
                       for (v, rep, addrs) in case['bursts']],
            'cache_pages': case['cache_pages'],
            'costs': {'hit': case['costs'][0], 'miss': case['costs'][1],
                      'decode': case['costs'][2]},
        }
        cases.append(case)
        raw_cases.append(raw)
    return {'cases': raw_cases}, cases

def run_one(seed, ncases=1, R_cap=5, verbose=False):
    rng = random.Random(seed)
    request, cases = build_request(rng, ncases, R_cap)
    if not request['cases']:
        return True
    payload = json.dumps(request).encode()
    p = subprocess.run([sys.executable, '-B', '/workspace/submission/main.py'],
                       input=payload, stdout=subprocess.PIPE,
                       stderr=subprocess.PIPE, cwd='/workspace')
    if p.returncode != 0:
        print('seed', seed, 'ENGINE CRASH', p.stderr[:400])
        return False
    actual = json.loads(p.stdout)
    gold_cases = []
    for case in cases:
        gv = []
        for h in case['history']:
            runs = brutelib.compile_runs(h)
            gv.append({'starts': [format(s, '032x') if s < U else '1' + '0' * 32
                                  for s, _ in runs],
                       'hops': [hop for _, hop in runs]})
        ch = []
        for t in range(len(case['transactions'])):
            rows = brutelib.changes(brutelib.compile_runs(case['history'][t]),
                                    brutelib.compile_runs(case['history'][t + 1]))
            ch.append([[format(a, '032x') if a < U else '1' + '0' * 32,
                        format(b, '032x') if b < U else '1' + '0' * 32, o, n]
                       for (a, b, o, n) in rows])
        # per-version brute + combined optimum
        per = []
        for v, h in enumerate(case['history']):
            runs = brutelib.compile_runs(h)
            starts = [s for s, _ in runs]
            bl = []
            for (bv, rep, addrs) in case['bursts']:
                if bv != v:
                    continue
                cnt = [0] * len(starts)
                for a in addrs:
                    idx = max(i for i in range(len(starts)) if starts[i] <= a)
                    cnt[idx] += 1
                bl.append((rep, cnt))
            if len(starts) <= 3:
                byres = brutelib.brute_full(starts, bl, case['cache_pages'],
                                            *case['costs'])
            else:
                byres = brutelib.brute_pruned(starts, bl, case['cache_pages'],
                                              *case['costs'])
            per.append((byres, runs))
        comb = brutelib.combine([b for b, _ in per], case['cache_pages'])
        const = sum(1 + (len(runs) * 4 + 63) // 64 for _, runs in per)
        gold_cases.append({'versions': gv, 'changes': ch,
                           'objective': [comb[0], comb[1] + const]})
    gold = {'cases': gold_cases}
    try:
        audit(request, actual, gold)
    except ValueError as e:
        print('seed', seed, 'AUDIT FAIL:', e)
        print('gold objective:', [c['objective'] for c in gold_cases])
        if isinstance(actual, dict) and 'cases' in actual:
            print('actual objective:', [c.get('objective') for c in actual['cases']])
        else:
            print('actual:', actual)
        open(f'/workspace/tmp/tests/fail-{seed}.json', 'w').write(
            json.dumps({'request': request, 'actual': actual, 'gold': gold},
                       default=str))
        return False
    if verbose:
        print('seed', seed, 'ok', [c['objective'] for c in gold_cases])
    return True

if __name__ == '__main__':
    lo, hi = int(sys.argv[1]), int(sys.argv[2])
    ncases = int(sys.argv[3]) if len(sys.argv) > 3 else 1
    R_cap = int(sys.argv[4]) if len(sys.argv) > 4 else 5
    fails = 0
    for seed in range(lo, hi):
        if not run_one(seed, ncases, R_cap):
            fails += 1
            if fails > 3:
                break
    print('DONE seeds', lo, hi, 'fails', fails)
